# Agent K=B: document, order, referral, claim_attachment designed; estimate and encounter_diagnosis decided NOT needed.
# Metadata only: no note text, no names, no patient numbers. Hashes and flags only.

# ======================================================================================= document
add("document", I_, "2 Encounter", "header",
    "One row per clinical or administrative document in the EMR (visit note, consent, advance notice, plan of care, result, letter, document pack): who, when, status, signatures. Never the content.",
    "The metadata layer for documentation work. It lets agents chase unsigned notes, check what a note documents, prove a consent or order is on file, and track which documents go with an authorization request or claim. Versioned: each change in status or signature is a new row, so signature lag and late entries can be measured as they were known.",
    "Unsigned-note count and age, signature lag, late-entry rate, addendum rate, co-signature backlog, documentation completeness by service group, consent on-file rate, share of authorization requests with a complete document pack",
    "1 EHR document and note index (metadata export or HL7 MDM), 2 EHR note-status report from the PM, 3 summary on the encounter (note_status, note_signed_date, elements_documented) with one rebuilt row per encounter, 4 none (Note Chaser then reads only the encounter columns)",
    common("document") + [
        L("document_number", "VARCHAR(50)", M_, "", "The EMR's own ID for the note or document. Makes loads repeatable. Restricted.", "Hash of encounter, document type and start date", True),
        L("practice_id", "INT", I_, "practice", "Reports by practice.", "From the encounter"),
        L("patient_id", "BIGINT", I_, "patient", "Which patient's chart. Hashed identity only.", "From the encounter"),
        L("document_class", "VARCHAR(20)", M_, "", "Broad family: note, consent, notice, plan_of_care, order_document, referral_document, result, letter, pack. Lets agents ask for all notes or all consents.", "Derived from the document type"),
        L("document_type", "VARCHAR(30)", M_, "", "Specific type: progress_note, procedure_note, consult, discharge, telephone, addendum, treatment_consent, telehealth_consent, financial_consent, release_of_information, advance_notice, lab_result, imaging_result, letter_of_medical_necessity, cover_note and so on.", "'progress_note' for any visit document"),
        L("document_status", "VARCHAR(20)", M_, "", "Where the document stands: not_started, draft, pended, signed, locked, amended, entered_in_error; for consents and notices on_file, missing, expired, withdrawn; for results received, reviewed. Drives the chase list.", "Derived from the encounter's note_status"),
        L("encounter_id", "BIGINT", I_, "encounter", "The visit the document belongs to. Blank for a standing consent.", "Match on patient and document date"),
        L("authorization_id", "BIGINT", I_, "authorization", "The authorization request the document supports (the supporting-information link). Blank otherwise.", "Blank"),
        L("claim_id", "BIGINT", I_, "claim", "The claim the document supports, for attachments and records requests. Blank otherwise.", "Blank"),
        L("author_provider_id", "INT", I_, "provider", "The clinician who wrote or signed it (internal provider, never a name).", "Rendering provider of the encounter"),
        L("signer_role", "VARCHAR(20)", O_, "", "Role of the signer: physician, nurse_practitioner, physician_assistant, resident, therapist, other. Supervision and incident-to rules depend on it.", "Blank; read from the provider's credential"),
        L("document_date", "DATE", I_, "", "Date the document was started (note date, consent date). Late entries are measured against the visit date.", "Encounter date"),
        L("signed_at", "DATETIME2(0)", I_, "", "Date and time of the signature. Signature lag and the time of day a note is signed.", "Encounter.note_signed_date at 00:00"),
        L("is_late_entry", "BIT", I_, "", "1 if written well after the visit. Payers question late notes.", "Signed date minus visit date over the practice's late-entry limit"),
        L("is_addendum", "BIT", I_, "", "1 if this row is a later addition to a signed note. The date of the addendum is its signed_at.", "document_type = addendum"),
        L("addendum_of_document_id", "BIGINT", O_, "document", "The original note this addendum adds to.", "Blank"),
        L("is_locked", "BIT", O_, "", "1 if the document is locked and cannot be edited. A locked unsigned note is a different fix.", "Status = locked"),
        L("cosign_required", "BIT", I_, "", "1 if a second signature is needed (supervision rule).", "Derived from signer role and payer rule; blank if unknown"),
        L("cosign_status", "VARCHAR(10)", O_, "", "not_needed, pending or done.", "Blank when cosign_required is blank"),
        L("cosigned_at", "DATETIME2(0)", O_, "", "When the co-signature was added.", "Blank until done"),
        L("expiry_date", "DATE", O_, "", "When a consent or plan of care stops being valid.", "Blank means no expiry"),
        L("elements_documented", "VARCHAR(300)", I_, "", "List of named elements found in the note (chief_complaint, history_present, exam, assessment, plan, diagnosis_linked, procedure_note, laterality, result, medical_necessity, mdm, telehealth_statements). Codes only, never text. The count goes on the encounter.", "Blank; encounter.elements_documented count only"),
        L("minutes_documented", "SMALLINT", I_, "", "Minutes written in the note; compared with visit minutes for time-based codes.", "Blank"),
        L("hpi_component_count", "TINYINT", O_, "", "Number of history-of-present-illness details found; supports the code-level check.", "Blank"),
        L("ros_system_count", "TINYINT", O_, "", "Number of body systems reviewed; supports the code-level check.", "Blank"),
        L("mdm_problem_level", "VARCHAR(10)", O_, "", "Problems addressed: minimal, low, moderate or high (decision-making input).", "Blank"),
        L("mdm_data_level", "VARCHAR(10)", O_, "", "Data reviewed: minimal, limited, moderate or extensive.", "Blank"),
        L("mdm_risk_level", "VARCHAR(10)", O_, "", "Risk of management: minimal, low, moderate or high.", "Blank"),
        L("content_hash", "CHAR(64)", I_, "", "SHA-256 hash of the document. Proves the same text was signed, sent or changed, without keeping it.", "Blank"),
        L("page_count", "SMALLINT", O_, "", "Pages in the document or pack.", "Blank"),
        L("document_type_code", "VARCHAR(20)", O_, "", "Standard code for the type (LOINC or the claim-attachment report type) when the payer needs it.", "Blank"),
        L("source_quality", "VARCHAR(20)", O_, "", "How readable the source is: structured, free_text, scanned_image, dictation. Scanned notes cannot be checked for elements.", "Blank means structured"),
    ] + audit("document"))

# ======================================================================================= order
add("order", O_, "2 Encounter", "header",
    "One row per clinical order (lab, imaging, procedure, equipment, therapy, referral out), with its status and the result status. Reserved word in SQL: always quoted.",
    "Tracks an order from ordered to resulted and links it to the visit line, the authorization and the signed order document. Finds orders that never became a charge and orders that need an authorization.",
    "Orders with no charge, orders awaiting result, orders signed late, ordered services that needed an authorization and had none, order volume by ordering provider",
    "1 EHR order feed, 2 encounter lines with line_status = ordered (one rebuilt order per line), 3 none (orders not tracked)",
    common("order") + [
        L("order_number", "VARCHAR(50)", M_, "", "The order number in the EMR. Makes loads repeatable. Restricted.", "Hash of patient, order type and order date", True),
        L("practice_id", "INT", I_, "practice", "Reports by practice.", "From the encounter"),
        L("patient_id", "BIGINT", I_, "patient", "Which patient. Hashed identity only.", "From the encounter"),
        L("encounter_id", "BIGINT", I_, "encounter", "The visit the order came from.", "Match on patient and order date"),
        L("encounter_detail_id", "BIGINT", O_, "encounter_details", "The visit line that records the order (line_status = ordered). From here, billing lines show whether a charge followed.", "Match on encounter and ordered code"),
        L("ordering_provider_id", "INT", I_, "provider", "Who ordered (internal provider, never a name).", "Ordering provider on the encounter line"),
        L("order_type", "VARCHAR(20)", M_, "", "lab, imaging, procedure, equipment, therapy, referral.", "Derived from the CPT code"),
        L("order_status", "VARCHAR(15)", M_, "", "draft, active, signed, completed, cancelled.", "'signed' when a signed date exists"),
        L("order_date", "DATE", I_, "", "Date the order was placed.", "Encounter date"),
        L("signed_date", "DATE", I_, "", "When the order was signed. Unsigned orders are often not payable.", "Blank means unsigned"),
        L("cpt_code_id", "INT", I_, "cpt_code", "What was ordered, when a code is known.", "Blank"),
        L("diagnosis_code_id", "INT", I_, "diagnosis_code", "Main diagnosis written on the order (medical necessity).", "Principal diagnosis of the encounter"),
        L("authorization_id", "BIGINT", I_, "authorization", "The authorization that covers the order, if one was needed.", "Match on patient, payer and code"),
        L("auth_required", "VARCHAR(7)", O_, "", "yes, no or unknown: whether the order needs an authorization.", "'unknown'"),
        L("document_id", "BIGINT", I_, "document", "The signed order document (metadata row).", "Blank"),
        L("result_status", "VARCHAR(10)", I_, "", "pending, received or reviewed. Orders without a reviewed result may need a follow-up.", "Blank when results are not tracked"),
        L("result_received_date", "DATE", O_, "", "When the result came back.", "Blank"),
        L("result_document_id", "BIGINT", O_, "document", "The result document (metadata row).", "Blank"),
    ] + audit("order"))

# ======================================================================================= referral
add("referral", I_, "1 Appointment", "header",
    "One row per referral into the practice: who referred, which payer and plan, valid dates, visits allowed and used.",
    "Referral-based denial prevention and visits remaining. Coverage only says that a referral is required; this table says whether a valid one exists for the visit. Versioned: visits used and status change over time.",
    "Visits without a valid referral, referrals expiring in 14 days, visits remaining, referral-related denial rate, referral-to-first-visit lag",
    "1 PM/EHR referral list, 2 payer referral portal or 278 response, 3 referring provider and flag on the encounter and coverage only",
    common("referral") + [
        L("referral_number", "VARCHAR(50)", M_, "", "The referral number in the EMR or on the payer side. Restricted.", "Hash of patient, referring provider and valid-from date", True),
        L("practice_id", "INT", I_, "practice", "Reports by practice.", "Client default"),
        L("patient_id", "BIGINT", M_, "patient", "Which patient. Hashed identity only.", "Hash of member ID"),
        L("coverage_id", "BIGINT", I_, "coverage", "The plan that requires the referral.", "Patient's current coverage"),
        L("payer_id", "INT", I_, "payer", "The payer that issued or requires the referral.", "Payer on the coverage"),
        L("referring_provider_id", "INT", M_, "provider", "The referring clinician (internal provider; the NPI sits on the provider row).", "Referring provider on the appointment"),
        L("referred_to_provider_id", "INT", I_, "provider", "The clinician in our practice the patient is referred to.", "Blank means any provider in the specialty"),
        L("specialty_id", "INT", I_, "specialty", "Specialty the referral is for.", "Specialty of the referred-to provider"),
        L("referral_status", "VARCHAR(15)", M_, "", "needed, requested, received, expired, used_up, cancelled.", "'received' when valid dates exist, else 'needed'"),
        L("request_date", "DATE", O_, "", "When the referral was requested. Request-to-receipt lag.", "Blank"),
        L("received_date", "DATE", O_, "", "When the referral arrived.", "Valid-from date"),
        L("valid_from", "DATE", I_, "", "First date the referral covers.", "Received date"),
        L("valid_to", "DATE", I_, "", "Last date the referral covers. Expiry warnings.", "Valid-from plus the payer's usual period"),
        L("visits_allowed", "SMALLINT", I_, "", "Visits approved.", "Blank means unlimited within dates"),
        L("visits_used", "SMALLINT", I_, "", "Visits already used. Visits remaining = allowed - used.", "Count of completed appointments inside the dates"),
        L("diagnosis_code_id", "INT", O_, "diagnosis_code", "Diagnosis on the referral.", "Blank"),
        L("cpt_code_id", "INT", O_, "cpt_code", "Service the referral names, when it names one.", "Blank"),
        L("authorization_id", "BIGINT", O_, "authorization", "Linked authorization, when the plan needs both.", "Blank"),
        L("document_id", "BIGINT", I_, "document", "The signed referral document (metadata row).", "Blank"),
    ] + audit("referral"))

# ======================================================================================= claim_attachment
add("claim_attachment", O_, "3 Bill and claim", "header",
    "One row per payer records request or attachment announcement for one claim: what was asked, when it is due, what we sent, and the payer's answer.",
    "Runs the payer-records workflow (pre-payment review, post-payment audit, attachment requests) and the attachment announcement on the claim. A request that covers several claims is several rows sharing the payer's reference number. Versioned: each status change (collecting, sent, acknowledged) is a new row.",
    "Open requests and days to due date, response lag, requests sent late, requests by payer and type, payer acknowledgement outcomes, claims denied for no attachment",
    "1 EHR or portal request log, 2 claim 277 status request and PWK segment on the 837, 3 manual entry from the request letter",
    common("claim_attachment") + [
        L("claim_attachment_number", "VARCHAR(50)", M_, "", "Our ID for this request or attachment row. Restricted.", "Generated: claim number and request type", True),
        L("practice_id", "INT", I_, "practice", "Reports by practice.", "From the claim"),
        L("patient_id", "BIGINT", I_, "patient", "Which patient. Hashed identity only.", "From the claim"),
        L("claim_id", "BIGINT", M_, "claim", "The claim the request or attachment is about.", "Match on payer claim number or control number"),
        L("payer_id", "INT", M_, "payer", "The payer that asked for the records or receives the attachment.", "Payer on the claim"),
        L("request_type", "VARCHAR(30)", M_, "", "pre_payment_review, post_payment_audit, attachment_request, medical_review, attachment_announcement (sent with the claim), other.", "'attachment_request'"),
        L("payer_reference_number", "VARCHAR(50)", I_, "", "The payer's reference for the request; groups rows from one request. Restricted.", "Blank", True),
        L("requesting_unit", "VARCHAR(30)", O_, "", "Review unit or audit vendor, for example medical_review, audit_vendor.", "Blank"),
        L("request_received_date", "DATE", I_, "", "Date the request arrived.", "Date the row was created"),
        L("request_channel", "VARCHAR(15)", I_, "", "How it arrived: mail, fax, portal, 277, emr_inbox, phone.", "Blank"),
        L("due_date", "DATE", I_, "", "Date the answer is due. Misses are lost money.", "Received date plus the payer's usual period"),
        L("extended_due_date", "DATE", O_, "", "Extension date, if the payer gave one.", "Blank"),
        L("documents_requested", "VARCHAR(300)", O_, "", "Document type codes asked for (matches document_type). Codes only.", "Blank means the whole chart for the visit"),
        L("request_text_hash", "CHAR(64)", O_, "", "SHA-256 hash of the request letter, not the letter.", "Blank"),
        L("response_status", "VARCHAR(20)", M_, "", "not_started, collecting, ready_for_review, sent, acknowledged, closed.", "'not_started'"),
        L("response_sent_date", "DATE", I_, "", "When our answer went out.", "Blank until sent"),
        L("response_method", "VARCHAR(15)", I_, "", "electronic, fax, mail, portal or courier.", "Blank until sent"),
        L("response_tracking_number", "VARCHAR(50)", O_, "", "Fax confirmation, portal receipt, courier number or 275 transaction number. Restricted.", "Blank", True),
        L("page_count", "SMALLINT", O_, "", "Pages sent or announced.", "Page count of the linked document"),
        L("payer_acknowledgement", "VARCHAR(15)", O_, "", "received, incomplete, accepted, rejected.", "Blank until the payer answers"),
        L("attachment_report_type_code", "VARCHAR(10)", O_, "", "What kind of document (report type on the claim announcement).", "Blank"),
        L("attachment_transmission_code", "VARCHAR(5)", O_, "", "How it is sent: electronic, fax or mail (transmission code).", "Blank"),
        L("attachment_control_number", "VARCHAR(50)", O_, "", "ID tying the claim to the later attachment. Restricted.", "Generated: claim number and sequence", True),
        L("document_id", "BIGINT", I_, "document", "The document or pack that went out (metadata row; hash and pages live there).", "Blank"),
    ] + audit("claim_attachment"))

